CREATE OR REPLACE FUNCTION public.apply_time_league_profile(p_league_id uuid, p_user_id uuid, p_seat text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_identity jsonb;
begin
    select identity into v_identity from time_league_profiles where user_id=p_user_id;
    if v_identity is null then return; end if;
    update time_leagues l set state=jsonb_set(l.state,'{teams}',(
        select jsonb_agg(case when t->>'teamId'=p_seat then t || jsonb_build_object('name',v_identity->>'teamName','helmet',v_identity->'helmet','primaryColor',v_identity->>'primaryColor','secondaryColor',v_identity->>'secondaryColor','backdrop',v_identity->>'backdrop') else t end order by n)
        from jsonb_array_elements(l.state->'teams') with ordinality a(t,n)
    )) where l.id=p_league_id;
end $function$

CREATE OR REPLACE FUNCTION public.change_app_password(p_user_id uuid, p_expected_version integer, p_expected_hash text, p_password_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_hash text;
  v_version integer;
  v_now timestamptz;
begin
  if p_user_id is null or p_expected_version is null or p_expected_version < 1
     or p_expected_hash is null
     or p_password_hash is null or p_password_hash !~ '^[0-9a-f]{32}:[0-9a-f]{64}$' then
    raise exception 'Invalid password change arguments' using errcode = '22023';
  end if;
  -- Same account-first lock order as reset links: concurrent changes and resets
  -- serialize and never rotate a password verified against an obsolete snapshot.
  select u.password_hash, u.session_version into v_hash, v_version
  from public.app_users u where u.id = p_user_id for update;
  if not found or v_version <> p_expected_version or v_hash <> p_expected_hash then
    return false;
  end if;
  v_now := clock_timestamp();
  update public.app_users
  set password_hash = p_password_hash, session_version = session_version + 1,
      password_changed_at = v_now, updated_at = v_now
  where id = p_user_id;
  update public.password_reset_tokens set used_at = v_now
  where user_id = p_user_id and used_at is null;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.change_commish_ignored_task(p_user_id uuid, p_session_version integer, p_task_id text, p_state text, p_expected_revision integer, p_operation_id uuid, p_snapshot jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_current public.commish_ignored_tasks;
  v_operation public.commish_ignored_operations;
begin
  if p_task_id is null or octet_length(p_task_id) not between 1 and 512 or p_task_id ~ '[[:cntrl:]]'
    or p_state is null or p_state not in ('ignored', 'restored') or p_operation_id is null
    or p_expected_revision is null or p_expected_revision not between 0 and 2000000000
    or (p_snapshot is not null and (jsonb_typeof(p_snapshot) <> 'object' or octet_length(p_snapshot::text) > 8192
      or p_snapshot ->> 'id' is distinct from p_task_id)) then
    return jsonb_build_object('ok', false, 'code', 'invalid_request', 'error', 'Invalid task change.');
  end if;
  -- Serialize small per-account writes, including operation IDs reused across
  -- different tasks. This also closes the auth-check/revocation race.
  perform 1 from public.app_users where id = p_user_id and session_version = p_session_version for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'invalid_session', 'error', 'Sign in again.'); end if;
  select * into v_current from public.commish_ignored_tasks where user_id = p_user_id and task_id = p_task_id;
  select * into v_operation from public.commish_ignored_operations where user_id = p_user_id and operation_id = p_operation_id;
  if found then
    if v_operation.task_id <> p_task_id or v_operation.state <> p_state
      or v_operation.expected_revision <> p_expected_revision or v_operation.snapshot is distinct from p_snapshot then
      return jsonb_build_object('ok', false, 'accountId', p_user_id, 'code', 'operation_conflict',
        'error', 'This operation ID was already used for another change.', 'record', public.commish_ignored_record_json(v_current));
    end if;
    -- Return current truth, even when the original successful change has since
    -- been restored elsewhere. A lost-response retry never rewrites it.
    return jsonb_build_object('ok', true, 'accountId', p_user_id, 'record', public.commish_ignored_record_json(v_current),
      'appliedRevision', v_operation.applied_revision, 'duplicate', true);
  end if;
  if coalesce(v_current.revision, 0) <> p_expected_revision then
    return jsonb_build_object('ok', false, 'accountId', p_user_id, 'code', 'revision_conflict',
      'error', 'This task changed on another device. Reload your choices before trying again.',
      'record', public.commish_ignored_record_json(v_current));
  end if;
  insert into public.commish_ignored_tasks(user_id, task_id, state, revision, snapshot, updated_at)
  values (p_user_id, p_task_id, p_state, p_expected_revision + 1,
    case when p_state = 'restored' then coalesce(v_current.snapshot, p_snapshot) else p_snapshot end, clock_timestamp())
  on conflict (user_id, task_id) do update set state = excluded.state, revision = excluded.revision,
    snapshot = excluded.snapshot, updated_at = excluded.updated_at
  returning * into v_current;
  insert into public.commish_ignored_operations(user_id, operation_id, task_id, state, expected_revision, snapshot, applied_revision)
  values (p_user_id, p_operation_id, p_task_id, p_state, p_expected_revision, p_snapshot, v_current.revision);
  return jsonb_build_object('ok', true, 'accountId', p_user_id, 'record', public.commish_ignored_record_json(v_current),
    'appliedRevision', v_current.revision, 'duplicate', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.check_rate_limit(p_key text, p_limit integer, p_window_seconds integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_epoch        bigint;
  v_window_epoch bigint;
  v_window_start timestamptz;
  v_count        integer;
begin
  if p_key is null or p_window_seconds is null or p_window_seconds <= 0 then
    return json_build_object('allowed', true, 'count', 0, 'limit', p_limit, 'retry_after', 0);
  end if;

  v_epoch        := floor(extract(epoch from clock_timestamp()))::bigint;
  v_window_epoch := (v_epoch / p_window_seconds) * p_window_seconds;
  v_window_start := to_timestamp(v_window_epoch);

  insert into public.rate_limit_counters (bucket_key, window_start, count)
  values (p_key, v_window_start, 1)
  on conflict (bucket_key, window_start)
  do update set count = public.rate_limit_counters.count + 1,
                updated_at = now()
  returning count into v_count;

  if p_limit > 0 and v_count > p_limit then
    return json_build_object(
      'allowed',     false,
      'count',       v_count,
      'limit',       p_limit,
      'retry_after', greatest(1, p_window_seconds - (v_epoch - v_window_epoch))
    );
  end if;

  return json_build_object('allowed', true, 'count', v_count, 'limit', p_limit, 'retry_after', 0);
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_duat_campaign_invite(p_user_id uuid, p_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_room_id uuid; v_room duat_campaigns; v_member duat_campaign_members;
begin
    if p_user_id is null then raise exception 'Sign in to claim a faction'; end if;
    select room_id into v_room_id from duat_campaign_members where invite_code=p_code;
    if v_room_id is null then raise exception 'This invitation does not exist'; end if;
    -- Lock the room first for the same ordering as readiness and game actions.
    select * into v_room from duat_campaigns where id=v_room_id for update;
    select * into v_member from duat_campaign_members where invite_code=p_code for update;
    if v_member.user_id=p_user_id then return v_room_id; end if;
    if v_member.user_id is not null then raise exception 'This faction already has an owner'; end if;
    if not (v_room.state->>'phase'='preseason' or (v_room.state->>'phase'='draft' and v_room.state#>>'{draft,status}'='waiting')) then raise exception 'The campaign has started; seats are locked'; end if;
    if exists(select 1 from duat_campaign_members where room_id=v_room_id and user_id=p_user_id) then raise exception 'You already own a faction in this campaign'; end if;
    update duat_campaign_members set user_id=p_user_id,joined_at=now(),ready=false where room_id=v_room_id and faction_id=v_member.faction_id;
    update duat_campaigns set revision=revision+1,updated_at=now() where id=v_room_id;
    return v_room_id;
end $function$

CREATE OR REPLACE FUNCTION public.claim_game_guest_invite(p_game text, p_code text, p_display_name text, p_token_hash text)
 RETURNS SETOF game_guest_sessions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_room uuid;
    v_guest public.game_guest_sessions;
    v_vault public.time_leagues;
    v_vault_member public.time_league_members;
    v_duat public.duat_campaigns;
    v_duat_member public.duat_campaign_members;
    v_owner uuid;
    v_role text;
    v_user uuid;
begin
    if p_game is null or p_game not in ('vault','duat') or p_code is null or p_code !~ '^[0-9a-f]{48}$'
        or p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$'
        or p_display_name is null or length(btrim(p_display_name)) not between 1 and 60
        or p_display_name ~ '[[:cntrl:]]' then raise exception 'Use a valid invitation and display name'; end if;
    -- A lost response can be retried with the browser's saved secret, including
    -- when two initial requests arrive together. The hash cannot change seats.
    perform pg_advisory_xact_lock(hashtextextended('game-guest:' || p_token_hash,0));
    if p_game='vault' then
        select league_id into v_room from public.time_league_members where invite_code=p_code;
        if v_room is null then raise exception 'This invitation does not exist'; end if;
        select * into v_vault from public.time_leagues where id=v_room for update;
        select * into v_vault_member from public.time_league_members where invite_code=p_code for update;
        v_owner:=v_vault_member.user_id; v_role:=v_vault_member.role;
    else
        select room_id into v_room from public.duat_campaign_members where invite_code=p_code;
        if v_room is null then raise exception 'This invitation does not exist'; end if;
        select * into v_duat from public.duat_campaigns where id=v_room for update;
        select * into v_duat_member from public.duat_campaign_members where invite_code=p_code for update;
        v_owner:=v_duat_member.user_id; v_role:=v_duat_member.role;
    end if;
    select * into v_guest from public.game_guest_sessions where token_hash=p_token_hash;
    if found then
        if v_guest.game<>p_game or v_guest.room_id<>v_room or v_owner is distinct from v_guest.app_user_id
            then raise exception 'This guest pass belongs to another seat'; end if;
        if v_guest.revoked_at is not null or v_guest.expires_at<=clock_timestamp() then raise exception 'This guest pass has expired or is unavailable'; end if;
        return next v_guest; return;
    end if;
    if v_role is distinct from 'member' or v_owner is not null then raise exception 'This seat has already been claimed'; end if;
    if p_game='vault' and (v_vault.draft_started or v_vault.phase is distinct from 'draft') then raise exception 'This draft has already started'; end if;
    if p_game='duat' and not coalesce(v_duat.state->>'phase'='preseason' or (v_duat.state->>'phase'='draft' and v_duat.state#>>'{draft,status}'='waiting'),false)
        then raise exception 'The campaign has started; seats are locked'; end if;
    v_user:=gen_random_uuid();
    insert into public.app_users(id,email,password_hash,display_name)
        values(v_user,'guest-' || v_user::text || '@guests.invalid','guest:' || gen_random_uuid()::text,btrim(p_display_name));
    if p_game='vault' then
        perform public.claim_time_league_invite(v_user,p_code);
    else
        perform public.claim_duat_campaign_invite(v_user,p_code);
    end if;
    insert into public.game_guest_sessions(token_hash,game,room_id,app_user_id,display_name,expires_at)
        values(p_token_hash,p_game,v_room,v_user,btrim(p_display_name),clock_timestamp()+interval '180 days') returning * into v_guest;
    return next v_guest;
end $function$

CREATE OR REPLACE FUNCTION public.claim_time_league_invite(p_user_id uuid, p_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_member time_league_members; v_league time_leagues; v_id uuid;
begin
    select league_id into v_id from time_league_members where invite_code=p_code;
    if not found then raise exception 'This invitation does not exist'; end if;
    select * into v_league from time_leagues where id=v_id for update;
    select * into v_member from time_league_members where invite_code=p_code for update;
    if v_member.user_id=p_user_id then return v_id; end if;
    if v_member.user_id is not null then raise exception 'This seat has already been claimed'; end if;
    if v_league.draft_started or v_league.phase<>'draft' then raise exception 'This draft has already started'; end if;
    if exists(select 1 from time_league_members where league_id=v_id and user_id=p_user_id) then raise exception 'You already have a seat in this league'; end if;
    update time_league_members set user_id=p_user_id,joined_at=now() where id=v_member.id;
    perform apply_time_league_profile(v_id,p_user_id,v_member.seat_team_id);
    update time_leagues set version=version+1 where id=v_id;
    return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.commit_duat_campaign_action(p_user_id uuid, p_room_id uuid, p_expected_revision integer, p_action_id text, p_action jsonb, p_next_state jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_room duat_campaigns; v_member duat_campaign_members; v_receipt duat_campaign_actions;
    v_type text; v_ready boolean; v_revision integer; v_cursor integer; v_position integer; v_turn text;
    v_size integer; v_rounds integer; v_dynasty boolean; v_cycle integer; v_own jsonb;
begin
    if p_user_id is null or p_action_id is null or length(p_action_id) not between 1 and 120 or jsonb_typeof(p_action) is distinct from 'object' then raise exception 'Invalid campaign action'; end if;
    select * into v_room from duat_campaigns where id=p_room_id for update;
    if not found then raise exception 'Campaign not found'; end if;
    select * into v_member from duat_campaign_members where room_id=p_room_id and user_id=p_user_id and joined_at is not null;
    if not found then raise exception 'You do not have a faction in this campaign'; end if;
    select * into v_receipt from duat_campaign_actions where room_id=p_room_id and user_id=p_user_id and action_id=p_action_id;
    if found then
        if v_receipt.request is distinct from p_action then raise exception 'This action ID was already used for another intent'; end if;
        return jsonb_build_object('ok',true,'revision',v_room.revision,'deduplicated',true);
    end if;
    if p_expected_revision is null or p_expected_revision<>v_room.revision then return jsonb_build_object('ok',false,'conflict',true,'revision',v_room.revision); end if;
    v_type := p_action->>'type';
    v_dynasty := coalesce(v_room.state->>'version'='4' and v_room.state->>'expansionVersion'='1',false);
    if v_type not in ('set-ready','start-draft','draft-pick','reveal-next','reveal-rulers','set-lineup','declare-favor','clear-favor','claim','attack','fortify','advance-week',
        'name-ruler','name-alliance','ritual','propose-pinnacle','approve-pinnacle','decline-pinnacle','next-season','reveal-years','address-ruler') or v_type is null then raise exception 'Unknown Duat action'; end if;
    if not v_dynasty and v_type in ('name-ruler','name-alliance','ritual','propose-pinnacle','approve-pinnacle','decline-pinnacle','next-season','reveal-years','address-ruler') then raise exception 'This action requires a sourcebook dynasty'; end if;
    if p_action ? 'factionId' and p_action->>'factionId' is distinct from v_member.faction_id then raise exception 'You can only control your own faction'; end if;
    select f into v_own from jsonb_array_elements(v_room.state->'factions') f where f->>'id'=v_member.faction_id;
    if v_room.state->>'phase'='complete' and (not v_dynasty or v_type not in ('set-ready','next-season','ritual','claim','attack','reveal-years','address-ruler')) then raise exception 'This campaign is complete'; end if;
    if v_type='reveal-years' and (not v_dynasty or v_room.state#>>'{era,hiddenYears}' is distinct from 'true' or v_room.state->>'phase' is distinct from 'complete') then raise exception 'Reveal scoring years from the final season recap'; end if;
    if v_type='ritual' and v_room.state->>'phase'='complete' and
        (p_action->>'ritualId' not in ('amun','plutus') or p_action->>'ritualId' is null or v_room.state->>'championId' is distinct from v_member.faction_id)
        then raise exception 'Only the reigning champion may enter the Throne Room'; end if;
    if v_type in ('start-draft','reveal-next','reveal-rulers','advance-week','next-season') then
        if v_member.role<>'host' then raise exception 'Only the host can advance the campaign'; end if;
        if exists(select 1 from duat_campaign_members where room_id=p_room_id and (user_id is null or joined_at is null or not ready)) then raise exception 'Every human faction must join and be ready'; end if;
        if v_dynasty and exists(select 1 from jsonb_array_elements(v_room.state->'factions') f where f#>'{rituals,pendingMahdi}' is not null and f#>'{rituals,pendingMahdi}'<>'null'::jsonb) then raise exception 'Accept or decline every waiting Mahdi recruit before advancing'; end if;
        if (v_type='reveal-rulers' and v_room.state->>'phase'<>'preseason')
            or (v_type='advance-week' and v_room.state->>'phase'<>'season')
            or (v_type='next-season' and v_room.state->>'phase'<>'complete')
            or (v_type='start-draft' and (v_room.state->>'phase'<>'draft' or v_room.state#>>'{draft,status}'<>'waiting'))
            or (v_type='reveal-next' and v_room.state->>'phase'<>'reveal') then raise exception 'That campaign stage is not open'; end if;
    end if;
    if v_type='draft-pick' then
        if v_room.state->>'phase'<>'draft' or v_room.state#>>'{draft,status}'<>'active' then raise exception 'This draft is not accepting picks'; end if;
        v_cursor := (v_room.state#>>'{draft,cursor}')::integer;
        if v_dynasty then
            -- Refilling damaged tombs and champion claims can make rounds uneven.
            -- The engine's explicit queue, not a modulus, determines the actor.
            v_turn := v_room.state#>'{draft,queue}'->v_cursor->>'factionId';
        else
            v_size := jsonb_array_length(v_room.state->'factions');
            v_rounds := (v_room.state#>>'{draft,totalPicks}')::integer / v_size / jsonb_array_length(v_room.state->'seasons');
            v_position := mod(v_cursor,v_size);
            if mod(mod(v_cursor,v_size*v_rounds) / v_size,2)=1 then v_position := v_size-1-v_position; end if;
            v_turn := v_room.state#>'{draft,order}'->>v_position;
        end if;
        if v_turn is distinct from v_member.faction_id then raise exception 'Wait for your faction turn to draft'; end if;
    end if;
    if v_type='set-ready' and v_room.state->>'phase'='draft' and v_room.state#>>'{draft,status}'<>'waiting' then raise exception 'Readiness is not used during draft turns'; end if;
    if v_type='set-ready' and v_room.state->>'phase'='reveal' and jsonb_array_length(v_room.state#>'{archaeology,revealedFactionIds}')>0 then raise exception 'The expedition has begun; readiness returns in Week 1'; end if;
    if v_type in ('set-lineup','declare-favor','clear-favor','name-ruler','name-alliance','ritual','propose-pinnacle','approve-pinnacle','decline-pinnacle') and v_member.ready then raise exception 'Mark yourself unready before changing dynasty decisions'; end if;
    if v_type='set-ready' then
        if jsonb_typeof(p_action->'ready') is distinct from 'boolean' or p_next_state is not null then raise exception 'Invalid readiness action'; end if;
        v_ready := (p_action->>'ready')::boolean;
        if v_ready and v_dynasty and v_own#>'{rituals,pendingMahdi}' is not null and v_own#>'{rituals,pendingMahdi}'<>'null'::jsonb then raise exception 'Accept or decline your waiting Mahdi recruit before becoming ready'; end if;
        update duat_campaign_members set ready=v_ready where room_id=p_room_id and faction_id=v_member.faction_id;
    else
        if jsonb_typeof(p_next_state) is distinct from 'object' or p_next_state->>'id' is distinct from v_room.state->>'id'
            or p_next_state->'humanFactionIds' is distinct from v_room.state->'humanFactionIds'
            or p_next_state->>'hostFactionId' is distinct from v_room.state->>'hostFactionId'
            or p_next_state->>'version' is distinct from v_room.state->>'version'
            or p_next_state->'settings' is distinct from v_room.state->'settings'
            or p_next_state->'scoring' is distinct from v_room.state->'scoring'
            or p_next_state->'era' is distinct from v_room.state->'era'
            or p_next_state->>'seed' is distinct from v_room.state->>'seed'
            or (select jsonb_agg(f->>'id') from jsonb_array_elements(p_next_state->'factions') f) is distinct from (select jsonb_agg(f->>'id') from jsonb_array_elements(v_room.state->'factions') f)
            then raise exception 'Invalid authoritative campaign state'; end if;
        if v_room.state#>>'{era,hiddenYears}'='true' then
            if p_next_state#>>'{hiddenYears,version}' is distinct from '1'
                or jsonb_typeof(p_next_state#>'{hiddenYears,assignments}') is distinct from 'object'
                or exists(select 1 from jsonb_each(v_room.state#>'{hiddenYears,assignments}') old where p_next_state#>'{hiddenYears,assignments}'->old.key is distinct from old.value)
                then raise exception 'Fixed hidden scoring years cannot change'; end if;
            if v_type not in ('start-draft','draft-pick','ritual','next-season') and p_next_state#>'{hiddenYears,assignments}' is distinct from v_room.state#>'{hiddenYears,assignments}' then raise exception 'Only new player acquisition may assign a hidden year'; end if;
            if v_type='reveal-years' then
                if (p_next_state - 'updatedAt' - 'hiddenYears') is distinct from (v_room.state - 'updatedAt' - 'hiddenYears')
                    or ((p_next_state#>'{hiddenYears,revealedByFaction}') - v_member.faction_id) is distinct from ((v_room.state#>'{hiddenYears,revealedByFaction}') - v_member.faction_id)
                    then raise exception 'A recap reveal cannot rewrite game state or another manager'; end if;
            elsif p_next_state#>'{hiddenYears,revealedByFaction}' is distinct from v_room.state#>'{hiddenYears,revealedByFaction}' then raise exception 'Only recap acknowledgement reveals scoring years'; end if;
        end if;
        if v_dynasty then
            v_cycle := (v_room.state->>'dynastySeason')::integer;
            if p_next_state->>'expansionVersion' is distinct from v_room.state->>'expansionVersion'
                or p_next_state->'expansionSettings' is distinct from v_room.state->'expansionSettings'
                or p_next_state->'calendarVersion' is distinct from v_room.state->'calendarVersion'
                or p_next_state->>'createdAt' is distinct from v_room.state->>'createdAt'
                or p_next_state->>'name' is distinct from v_room.state->>'name'
                then raise exception 'Invalid immutable dynasty rules'; end if;
            if v_type='next-season' then
                if p_next_state->>'phase' is distinct from 'draft' or p_next_state->>'week' is distinct from '1'
                    or (p_next_state->>'dynastySeason')::integer is distinct from v_cycle+1
                    or (p_next_state#>>'{dynasty,cycle}')::integer is distinct from v_cycle+1
                    then raise exception 'A dynasty may advance exactly one season'; end if;
            elsif p_next_state->'dynastySeason' is distinct from v_room.state->'dynastySeason'
                or p_next_state#>'{dynasty,cycle}' is distinct from v_room.state#>'{dynasty,cycle}' then raise exception 'Only next-season may change the dynasty cycle'; end if;
            if v_type not in ('ritual','next-season') and p_next_state->'seasons' is distinct from v_room.state->'seasons' then raise exception 'Only a ritual or next-season may change historical years'; end if;
            if jsonb_typeof(p_next_state->'seasons') is distinct from 'array' or jsonb_array_length(p_next_state->'seasons') not between 1 and 24
                or (select count(distinct value) from jsonb_array_elements(p_next_state->'seasons')) <> jsonb_array_length(p_next_state->'seasons')
                or exists(select 1 from jsonb_array_elements(p_next_state->'seasons') y where jsonb_typeof(y)<>'number' or y::text !~ '^[0-9]{4}$' or (y::text)::integer not between 1920 and 2100)
                then raise exception 'Invalid dynasty historical years'; end if;
        elsif p_next_state->'seasons' is distinct from v_room.state->'seasons' then raise exception 'Invalid authoritative campaign state'; end if;
        if v_type='address-ruler' then
            if (p_next_state - 'updatedAt' - 'council') is distinct from (v_room.state - 'updatedAt' - 'council')
                or p_next_state#>>'{council,version}' is distinct from '1'
                or jsonb_typeof(p_next_state#>'{council,messages}') is distinct from 'array'
                or jsonb_array_length(p_next_state#>'{council,messages}') not between 1 and 400
                then raise exception 'Council conversations may only update their saved exchanges'; end if;
            if p_next_state->'council' is distinct from v_room.state->'council' then
                if (p_next_state#>'{council,messages}')->-1->>'fromFactionId' is distinct from v_member.faction_id
                    or (p_next_state#>'{council,messages}')->-1->>'toFactionId' is distinct from p_action->>'targetFactionId'
                    or (p_next_state#>'{council,messages}')->-1->>'id' is distinct from p_action->>'messageId'
                    or ((p_next_state#>'{council,messages}') - (jsonb_array_length(p_next_state#>'{council,messages}')-1)) is distinct from
                        (case when jsonb_array_length(coalesce(v_room.state#>'{council,messages}','[]'::jsonb))=400
                            then (v_room.state#>'{council,messages}') - 0 else coalesce(v_room.state#>'{council,messages}','[]'::jsonb) end)
                    then raise exception 'Append only the acting managers council exchange'; end if;
            end if;
        elsif p_next_state->'council' is distinct from v_room.state->'council' then
            raise exception 'Only addressing a ruler may change council conversations';
        end if;
        update duat_campaigns set state=p_next_state where id=p_room_id;
        if v_type in ('start-draft','reveal-rulers','advance-week','next-season') or (v_type='reveal-next' and p_next_state->>'phase'='season') then update duat_campaign_members set ready=false where room_id=p_room_id; end if;
    end if;
    update duat_campaigns set revision=revision+1,updated_at=now() where id=p_room_id returning revision into v_revision;
    insert into duat_campaign_actions(room_id,user_id,action_id,request,revision) values(p_room_id,p_user_id,p_action_id,p_action,v_revision);
    return jsonb_build_object('ok',true,'revision',v_revision);
end $function$

CREATE OR REPLACE FUNCTION public.confirm_app_password_reset(p_token_hash text, p_password_hash text)
 RETURNS TABLE(user_id uuid, email text, session_version integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_token_id uuid;
  v_now timestamptz;
begin
  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$'
     or p_password_hash is null or p_password_hash !~ '^[0-9a-f]{32}:[0-9a-f]{64}$' then
    raise exception 'Invalid password reset arguments' using errcode = '22023';
  end if;

  select t.user_id into v_user_id
  from public.password_reset_tokens t where t.token_hash = p_token_hash;
  if not found then return; end if;

  -- Serialize by account before locking any token, including competing reset
  -- links for the same account. This order avoids cross-token deadlocks.
  perform 1 from public.app_users u where u.id = v_user_id for update;
  if not found then return; end if;

  -- Recheck after waiting for the account lock. Wall time matters if the link
  -- expired during that wait; transaction-start now() would accept it.
  v_now := clock_timestamp();
  select t.id into v_token_id
  from public.password_reset_tokens t
  where t.token_hash = p_token_hash and t.user_id = v_user_id
    and t.used_at is null and t.expires_at > v_now
  for update;
  if not found then return; end if;

  update public.app_users u
  set password_hash = p_password_hash,
      session_version = u.session_version + 1,
      password_changed_at = v_now,
      updated_at = v_now
  where u.id = v_user_id;

  -- A completed reset also invalidates other already-issued links for this
  -- account. No prior link should change the newly chosen password again.
  update public.password_reset_tokens t set used_at = v_now
  where t.user_id = v_user_id and t.used_at is null;

  return query select u.id, u.email, u.session_version
  from public.app_users u where u.id = v_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.consume_auth_rate_limit(p_scope text, p_identifier text, p_limit integer, p_window_seconds integer, p_lockout_seconds integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.auth_rate_limits%rowtype;
  stamp timestamptz;
  next_count integer;
  retry integer;
begin
  if p_scope is null or p_identifier is null or p_limit is null or p_window_seconds is null
     or p_lockout_seconds is null or p_limit < 1 or p_window_seconds < 1 or p_lockout_seconds < 0 then
    raise exception 'Invalid rate limit';
  end if;
  insert into public.auth_rate_limits(scope, identifier, attempt_count)
    values(p_scope, p_identifier, 0) on conflict(scope, identifier) do nothing;
  select * into strict r from public.auth_rate_limits
    where scope = p_scope and identifier = p_identifier for update;
  stamp := clock_timestamp();
  if r.locked_until > stamp then
    return jsonb_build_object('allowed', false, 'count', r.attempt_count,
      'retryAfterSeconds', greatest(1, ceil(extract(epoch from r.locked_until - stamp))::integer));
  end if;
  if r.window_start + make_interval(secs => p_window_seconds) <= stamp then
    r.window_start := stamp;
    r.attempt_count := 0;
  end if;
  next_count := least(r.attempt_count + 1, p_limit + 1);
  r.locked_until := case when next_count > p_limit and p_lockout_seconds > 0
    then stamp + make_interval(secs => p_lockout_seconds) else null end;
  update public.auth_rate_limits set attempt_count = next_count, window_start = r.window_start,
    locked_until = r.locked_until, updated_at = stamp
    where scope = p_scope and identifier = p_identifier;
  retry := greatest(1, ceil(extract(epoch from
    coalesce(r.locked_until, r.window_start + make_interval(secs => p_window_seconds)) - stamp))::integer);
  return jsonb_build_object('allowed', next_count <= p_limit, 'count', next_count,
    'retryAfterSeconds', case when next_count > p_limit then retry else 0 end);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_duat_campaign(p_user_id uuid, p_state jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_faction text; v_host text; v_humans text[]; v_size integer;
begin
    if p_user_id is null or jsonb_typeof(p_state) is distinct from 'object'
        or (((p_state->>'phase'='preseason' and p_state->>'version'='1')
        or (p_state->>'phase'='draft' and p_state->>'version' in ('2','3','4') and p_state#>>'{draft,status}'='waiting')) is not true)
        then raise exception 'Invalid new campaign'; end if;
    v_size := case when p_state->>'version' in ('3','4') then (p_state#>>'{settings,leagueSize}')::integer else 14 end;
    if v_size is null or v_size not in (8,10,12,14,16) then raise exception 'Invalid league size'; end if;
    if p_state->>'version'='4' and (p_state->>'expansionVersion' is distinct from '1'
        or p_state->>'dynastySeason' is distinct from '1' or p_state#>>'{dynasty,cycle}' is distinct from '1'
        or jsonb_typeof(p_state->'expansionSettings') is distinct from 'object'
        or jsonb_typeof(p_state#>'{draft,queue}') is distinct from 'array') then raise exception 'Invalid sourcebook dynasty'; end if;
    v_host := p_state->>'hostFactionId';
    select array_agg(value) into v_humans from jsonb_array_elements_text(p_state->'humanFactionIds');
    if v_host is null or coalesce(array_length(v_humans,1),0) not between 1 and v_size or not (v_host=any(v_humans))
        or (select count(distinct value) from unnest(v_humans) value) <> array_length(v_humans,1)
        or jsonb_array_length(p_state->'factions') is distinct from v_size
        or (select count(distinct f->>'id') from jsonb_array_elements(p_state->'factions') f) <> v_size
        or exists(select 1 from unnest(v_humans) h where not exists(select 1 from jsonb_array_elements(p_state->'factions') f where f->>'id'=h))
        then raise exception 'Choose unique human factions including the host'; end if;
    insert into duat_campaigns(created_by,state) values(p_user_id,p_state) returning id into v_id;
    foreach v_faction in array v_humans loop
        insert into duat_campaign_members(room_id,faction_id,role,user_id,joined_at)
        values(v_id,v_faction,case when v_faction=v_host then 'host' else 'member' end,
            case when v_faction=v_host then p_user_id else null end,
            case when v_faction=v_host then now() else null end);
    end loop;
    return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.create_time_league(p_user_id uuid, p_state jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_team jsonb; v_first boolean := true;
begin
    insert into time_leagues(created_by, state) values (p_user_id, p_state) returning id into v_id;
    for v_team in select value from jsonb_array_elements(p_state->'teams') loop
        if v_team->>'manager' = 'human' then
            insert into time_league_members(league_id, seat_team_id, role, user_id, joined_at)
            values(v_id, v_team->>'teamId', case when v_first then 'commissioner' else 'member' end,
                case when v_first then p_user_id else null end, case when v_first then now() else null end);
            v_first := false;
        end if;
    end loop;
    if v_first then raise exception 'At least one human seat is required'; end if;
    return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.current_app_user_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_claims jsonb := auth.jwt();
  v_user_id uuid;
  v_version integer;
begin
  begin
    v_user_id := (v_claims -> 'app_metadata' ->> 'user_id')::uuid;
    v_version := (v_claims -> 'app_metadata' ->> 'session_version')::integer;
  exception when invalid_text_representation or numeric_value_out_of_range then
    return null;
  end;
  if v_user_id is null or v_version is null or v_version < 1 then return null; end if;

  -- Definer access avoids recursion through app_users' own RLS policy. No
  -- caller-supplied ID argument or account data is exposed by this helper.
  return (select u.id from public.app_users u
          where u.id = v_user_id and u.session_version = v_version);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_ai_preference_summary(p_identifier text, p_league_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_identifier text := left(nullif(btrim(coalesce(p_identifier, '')), ''), 300);
  v_since timestamptz := now() - interval '90 days';
  v_up integer := 0;
  v_down integer := 0;
  v_acted integer := 0;
  v_dismissed integer := 0;
  v_total integer := 0;
  v_accept numeric := null;
  v_surfaces jsonb := '{}'::jsonb;
  v_recent_downs jsonb := '[]'::jsonb;
  v_recent_acted jsonb := '[]'::jsonb;
begin
  if v_identifier is null then
    return jsonb_build_object('total', 0);
  end if;

  select
    count(*) filter (where action = 'up'),
    count(*) filter (where action = 'down'),
    count(*) filter (where action = 'acted'),
    count(*) filter (where action = 'dismissed'),
    count(*)
  into v_up, v_down, v_acted, v_dismissed, v_total
  from public.ai_feedback
  where identifier = v_identifier
    and created_at >= v_since
    and (p_league_id is null or league_id = p_league_id);

  if v_total = 0 then
    return jsonb_build_object('total', 0);
  end if;

  if (v_up + v_acted + v_down) > 0 then
    v_accept := round((v_up + v_acted)::numeric / (v_up + v_acted + v_down), 2);
  end if;

  select coalesce(jsonb_object_agg(surface, counts), '{}'::jsonb)
  into v_surfaces
  from (
    select surface, jsonb_build_object(
      'up', count(*) filter (where action = 'up'),
      'down', count(*) filter (where action = 'down'),
      'acted', count(*) filter (where action = 'acted')
    ) as counts
    from public.ai_feedback
    where identifier = v_identifier
      and created_at >= v_since
      and (p_league_id is null or league_id = p_league_id)
    group by surface
  ) s;

  select coalesce(jsonb_agg(subject), '[]'::jsonb)
  into v_recent_downs
  from (
    select subject
    from public.ai_feedback
    where identifier = v_identifier
      and created_at >= v_since
      and action = 'down'
      and subject is not null
      and (p_league_id is null or league_id = p_league_id)
    order by created_at desc
    limit 5
  ) d;

  select coalesce(jsonb_agg(subject), '[]'::jsonb)
  into v_recent_acted
  from (
    select subject
    from public.ai_feedback
    where identifier = v_identifier
      and created_at >= v_since
      and action = 'acted'
      and subject is not null
      and (p_league_id is null or league_id = p_league_id)
    order by created_at desc
    limit 5
  ) a;

  return jsonb_build_object(
    'total', v_total,
    'upCount', v_up,
    'downCount', v_down,
    'actedCount', v_acted,
    'dismissedCount', v_dismissed,
    'acceptRate', v_accept,
    'surfaceCounts', v_surfaces,
    'recentDownSubjects', v_recent_downs,
    'recentActedSubjects', v_recent_acted
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.provision_gift_password(p_actor uuid, p_username text, p_password_hash text, p_display_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare changed integer;
begin
  if not exists(select 1 from public.app_user_roles where user_id = p_actor and role in ('admin', 'owner')) then
    raise exception 'Administrator required' using errcode = '42501';
  end if;
  if p_username is null or btrim(p_username) = '' or p_password_hash is null or p_password_hash = '' then
    raise exception 'Username and password hash required';
  end if;
  insert into public.users(sleeper_username, password_hash, display_name, is_gifted)
    values(p_username, p_password_hash, p_display_name, true)
    on conflict(sleeper_username) do update
      set password_hash = excluded.password_hash, display_name = excluded.display_name, is_gifted = true
      where public.users.password_hash is null or public.users.password_hash = '';
  get diagnostics changed = row_count;
  return changed = 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.read_commish_ignored_tasks(p_user_id uuid, p_session_version integer, p_cursor text DEFAULT NULL::text, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rows jsonb;
  v_cursor text := null;
begin
  if p_limit is null or p_limit < 1 or p_limit > 200 or (p_cursor is not null and octet_length(p_cursor) > 512) then
    return jsonb_build_object('ok', false, 'code', 'invalid_request', 'error', 'Invalid page request.');
  end if;
  perform 1 from public.app_users where id = p_user_id and session_version = p_session_version for share;
  if not found then return jsonb_build_object('ok', false, 'code', 'invalid_session', 'error', 'Sign in again.'); end if;
  select coalesce(jsonb_agg(page.record order by page.task_id collate "C"), '[]'::jsonb) into v_rows from (
    select t.task_id, public.commish_ignored_record_json(t) as record
    from public.commish_ignored_tasks t
    where t.user_id = p_user_id and (p_cursor is null or t.task_id collate "C" > p_cursor collate "C")
    order by t.task_id collate "C" limit p_limit + 1
  ) page;
  if jsonb_array_length(v_rows) > p_limit then
    v_cursor := v_rows -> (p_limit - 1) ->> 'taskId';
    v_rows := v_rows - p_limit;
  end if;
  return jsonb_build_object('ok', true, 'accountId', p_user_id, 'records', v_rows, 'nextCursor', v_cursor);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_ai_usage_result(p_identifier text, p_user_id uuid, p_username text, p_tier text, p_tokens integer, p_estimated_cost_usd numeric, p_reserved_cost_usd numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_identifier text := left(nullif(btrim(coalesce(p_identifier, '')), ''), 300);
  v_today date := current_date;
  v_month date := date_trunc('month', current_date)::date;
  v_daily public.ai_usage_daily%rowtype;
  v_monthly public.ai_usage_monthly%rowtype;
  v_tokens integer := greatest(coalesce(p_tokens, 0), 0);
  v_actual numeric := greatest(coalesce(p_estimated_cost_usd, 0), 0);
  v_reserved numeric := greatest(coalesce(p_reserved_cost_usd, 0), 0);
begin
  if v_identifier is null then
    return jsonb_build_object('recorded', false, 'reason', 'invalid_identifier');
  end if;

  insert into public.ai_usage_daily (
    usage_date, identifier, user_id, username, tier, tokens_used, estimated_cost_usd
  )
  values (
    v_today, v_identifier, p_user_id, p_username, coalesce(nullif(p_tier, ''), 'free'), v_tokens, v_actual
  )
  on conflict (identifier, usage_date)
  do update set
    tokens_used = public.ai_usage_daily.tokens_used + v_tokens,
    estimated_cost_usd = public.ai_usage_daily.estimated_cost_usd + v_actual,
    reserved_cost_usd = greatest(public.ai_usage_daily.reserved_cost_usd - v_reserved, 0),
    user_id = coalesce(p_user_id, public.ai_usage_daily.user_id),
    username = coalesce(p_username, public.ai_usage_daily.username),
    tier = coalesce(nullif(p_tier, ''), public.ai_usage_daily.tier),
    updated_at = now()
  returning * into v_daily;

  insert into public.ai_usage_monthly (
    month_start, identifier, user_id, username, tier, tokens_used, estimated_cost_usd
  )
  values (
    v_month, v_identifier, p_user_id, p_username, coalesce(nullif(p_tier, ''), 'free'), v_tokens, v_actual
  )
  on conflict (identifier, month_start)
  do update set
    tokens_used = public.ai_usage_monthly.tokens_used + v_tokens,
    estimated_cost_usd = public.ai_usage_monthly.estimated_cost_usd + v_actual,
    reserved_cost_usd = greatest(public.ai_usage_monthly.reserved_cost_usd - v_reserved, 0),
    user_id = coalesce(p_user_id, public.ai_usage_monthly.user_id),
    username = coalesce(p_username, public.ai_usage_monthly.username),
    tier = coalesce(nullif(p_tier, ''), public.ai_usage_monthly.tier),
    updated_at = now()
  returning * into v_monthly;

  return jsonb_build_object(
    'recorded', true,
    'dailyRequests', v_daily.request_count,
    'monthlyRequests', v_monthly.request_count,
    'dailyTokens', v_daily.tokens_used,
    'monthlyTokens', v_monthly.tokens_used,
    'dailyCostUsd', v_daily.estimated_cost_usd + v_daily.reserved_cost_usd,
    'monthlyCostUsd', v_monthly.estimated_cost_usd + v_monthly.reserved_cost_usd
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_ai_usage(p_identifier text, p_user_id uuid, p_username text, p_tier text, p_daily_request_limit integer, p_monthly_request_limit integer, p_daily_cost_limit numeric, p_monthly_cost_limit numeric, p_estimated_request_cost_usd numeric, p_global_daily_cost_limit numeric DEFAULT NULL::numeric, p_global_monthly_cost_limit numeric DEFAULT NULL::numeric, p_count_request boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_identifier text := left(nullif(btrim(coalesce(p_identifier, '')), ''), 300);
  v_today date := current_date;
  v_month date := date_trunc('month', current_date)::date;
  v_daily public.ai_usage_daily%rowtype;
  v_monthly public.ai_usage_monthly%rowtype;
  v_reserved numeric := greatest(coalesce(p_estimated_request_cost_usd, 0), 0);
  v_count boolean := coalesce(p_count_request, true);
  v_global_daily numeric := 0;
  v_global_monthly numeric := 0;
begin
  if v_identifier is null then
    return jsonb_build_object('allowed', false, 'reason', 'invalid_identifier');
  end if;

  if coalesce(p_daily_request_limit, 0) <= 0 or coalesce(p_monthly_request_limit, 0) <= 0 then
    return jsonb_build_object('allowed', false, 'reason', 'plan_disabled');
  end if;

  insert into public.ai_usage_daily (usage_date, identifier, user_id, username, tier)
  values (v_today, v_identifier, p_user_id, p_username, coalesce(nullif(p_tier, ''), 'free'))
  on conflict (identifier, usage_date) do nothing;

  insert into public.ai_usage_monthly (month_start, identifier, user_id, username, tier)
  values (v_month, v_identifier, p_user_id, p_username, coalesce(nullif(p_tier, ''), 'free'))
  on conflict (identifier, month_start) do nothing;

  select * into v_daily
  from public.ai_usage_daily
  where identifier = v_identifier and usage_date = v_today
  for update;

  select * into v_monthly
  from public.ai_usage_monthly
  where identifier = v_identifier and month_start = v_month
  for update;

  if v_count and v_daily.request_count >= p_daily_request_limit then
    return jsonb_build_object(
      'allowed', false,
      'reason', 'daily_requests',
      'dailyRequests', v_daily.request_count,
      'dailyRequestLimit', p_daily_request_limit,
      'monthlyRequests', v_monthly.request_count,
      'monthlyRequestLimit', p_monthly_request_limit
    );
  end if;

  if v_count and v_monthly.request_count >= p_monthly_request_limit then
    return jsonb_build_object(
      'allowed', false,
      'reason', 'monthly_requests',
      'dailyRequests', v_daily.request_count,
      'dailyRequestLimit', p_daily_request_limit,
      'monthlyRequests', v_monthly.request_count,
      'monthlyRequestLimit', p_monthly_request_limit
    );
  end if;

  if coalesce(p_daily_cost_limit, 0) > 0
     and (v_daily.estimated_cost_usd + v_daily.reserved_cost_usd + v_reserved) > p_daily_cost_limit then
    return jsonb_build_object(
      'allowed', false,
      'reason', 'daily_cost',
      'dailyCostUsd', v_daily.estimated_cost_usd + v_daily.reserved_cost_usd,
      'dailyCostLimitUsd', p_daily_cost_limit
    );
  end if;

  if coalesce(p_monthly_cost_limit, 0) > 0
     and (v_monthly.estimated_cost_usd + v_monthly.reserved_cost_usd + v_reserved) > p_monthly_cost_limit then
    return jsonb_build_object(
      'allowed', false,
      'reason', 'monthly_cost',
      'monthlyCostUsd', v_monthly.estimated_cost_usd + v_monthly.reserved_cost_usd,
      'monthlyCostLimitUsd', p_monthly_cost_limit
    );
  end if;

  if coalesce(p_global_daily_cost_limit, 0) > 0 then
    select coalesce(sum(estimated_cost_usd + reserved_cost_usd), 0)
      into v_global_daily
      from public.ai_usage_daily
      where usage_date = v_today;
    if v_global_daily + v_reserved > p_global_daily_cost_limit then
      return jsonb_build_object(
        'allowed', false,
        'reason', 'global_daily_cost',
        'globalDailyCostUsd', v_global_daily,
        'globalDailyCostLimitUsd', p_global_daily_cost_limit
      );
    end if;
  end if;

  if coalesce(p_global_monthly_cost_limit, 0) > 0 then
    select coalesce(sum(estimated_cost_usd + reserved_cost_usd), 0)
      into v_global_monthly
      from public.ai_usage_monthly
      where month_start = v_month;
    if v_global_monthly + v_reserved > p_global_monthly_cost_limit then
      return jsonb_build_object(
        'allowed', false,
        'reason', 'global_monthly_cost',
        'globalMonthlyCostUsd', v_global_monthly,
        'globalMonthlyCostLimitUsd', p_global_monthly_cost_limit
      );
    end if;
  end if;

  update public.ai_usage_daily
  set request_count = request_count + (case when v_count then 1 else 0 end),
      reserved_cost_usd = reserved_cost_usd + v_reserved,
      user_id = coalesce(p_user_id, user_id),
      username = coalesce(p_username, username),
      tier = coalesce(nullif(p_tier, ''), tier),
      updated_at = now()
  where identifier = v_identifier and usage_date = v_today
  returning * into v_daily;

  update public.ai_usage_monthly
  set request_count = request_count + (case when v_count then 1 else 0 end),
      reserved_cost_usd = reserved_cost_usd + v_reserved,
      user_id = coalesce(p_user_id, user_id),
      username = coalesce(p_username, username),
      tier = coalesce(nullif(p_tier, ''), tier),
      updated_at = now()
  where identifier = v_identifier and month_start = v_month
  returning * into v_monthly;

  return jsonb_build_object(
    'allowed', true,
    'requestCounted', v_count,
    'dailyRequests', v_daily.request_count,
    'dailyRequestLimit', p_daily_request_limit,
    'monthlyRequests', v_monthly.request_count,
    'monthlyRequestLimit', p_monthly_request_limit,
    'dailyCostUsd', v_daily.estimated_cost_usd + v_daily.reserved_cost_usd,
    'dailyCostLimitUsd', p_daily_cost_limit,
    'monthlyCostUsd', v_monthly.estimated_cost_usd + v_monthly.reserved_cost_usd,
    'monthlyCostLimitUsd', p_monthly_cost_limit,
    'reservedCostUsd', v_reserved
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_time_league_community_invite(p_user_id uuid, p_invite_id uuid, p_accept boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_invite time_league_community_invites; v_league time_leagues;
begin
    select * into v_invite from time_league_community_invites where id=p_invite_id and recipient_id=p_user_id;
    if not found then raise exception 'This invitation is not addressed to you'; end if;
    select * into v_league from time_leagues where id=v_invite.league_id for update;
    select * into v_invite from time_league_community_invites where id=p_invite_id for update;
    if v_invite.status='accepted' then return v_invite.league_id; end if;
    if v_invite.status<>'pending' then raise exception 'This invitation has already been answered'; end if;
    if p_accept then
        if v_league.draft_started or v_league.phase<>'draft' then raise exception 'This draft has already started'; end if;
        if exists(select 1 from time_league_members where league_id=v_invite.league_id and user_id=p_user_id) then raise exception 'You already have a seat in this league'; end if;
        update time_league_members set user_id=p_user_id,joined_at=now() where league_id=v_invite.league_id and seat_team_id=v_invite.seat_team_id and user_id is null;
        if not found then raise exception 'This seat has already been claimed'; end if;
        perform apply_time_league_profile(v_invite.league_id,p_user_id,v_invite.seat_team_id);
        update time_leagues set version=version+1 where id=v_invite.league_id;
    end if;
    update time_league_community_invites set status=case when p_accept then 'accepted' else 'declined' end,responded_at=now() where id=p_invite_id;
    return case when p_accept then v_invite.league_id else null end;
end $function$

CREATE OR REPLACE FUNCTION public.send_time_league_community_invite(p_user_id uuid, p_league_id uuid, p_seat_team_id text, p_profile_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_league time_leagues; v_target uuid; v_id uuid;
begin
    -- Serialize a sender's requests across leagues to enforce the daily limit.
    perform 1 from app_users where id=p_user_id for update;
    select * into v_league from time_leagues where id=p_league_id for update;
    if not found or not exists(select 1 from time_league_members where league_id=p_league_id and user_id=p_user_id and role='commissioner') then raise exception 'Only this league commissioner can invite a manager'; end if;
    if v_league.draft_started or v_league.phase<>'draft' then raise exception 'Invite managers before the draft starts'; end if;
    if not exists(select 1 from time_league_profiles where user_id=p_user_id) then raise exception 'Save your manager profile first'; end if;
    select user_id into v_target from time_league_profiles where profile_id=p_profile_id and public_profile and looking_for_league;
    if not found or v_target=p_user_id then raise exception 'This manager is not available for invitations'; end if;
    if exists(select 1 from time_league_members where league_id=p_league_id and user_id=v_target) then raise exception 'This manager already has a seat'; end if;
    if not exists(select 1 from time_league_members where league_id=p_league_id and seat_team_id=p_seat_team_id and user_id is null) then raise exception 'Choose an open human seat'; end if;
    if exists(select 1 from time_league_community_invites where league_id=p_league_id and recipient_id=v_target) then raise exception 'You already invited this manager to this league'; end if;
    if (select count(*) from time_league_community_invites where sender_id=p_user_id and created_at>now()-interval '1 day')>=24 then raise exception 'You have reached the daily limit of 24 invitations'; end if;
    insert into time_league_community_invites(league_id,seat_team_id,sender_id,recipient_id) values(p_league_id,p_seat_team_id,p_user_id,v_target) returning id into v_id;
    return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.send_time_league_message(p_user_id uuid, p_league_id uuid, p_expected_version integer, p_messages jsonb, p_relationship jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_game time_leagues; v_member time_league_members; v_first jsonb; v_message jsonb;
    v_existing jsonb; v_target jsonb; v_sender jsonb; v_count integer; v_index integer;
    v_week integer; v_message_week integer; v_heat integer; v_previous jsonb; v_relationships jsonb;
    v_now timestamptz := clock_timestamp(); v_reply text;
begin
    select * into v_game from time_leagues where id = p_league_id for update;
    if not found then raise exception 'This league is unavailable'; end if;
    select * into v_member from time_league_members where league_id = p_league_id and user_id = p_user_id and joined_at is not null;
    if not found then raise exception 'You need a joined seat to send messages'; end if;
    if jsonb_typeof(p_messages) is distinct from 'array' or jsonb_array_length(p_messages) not between 1 and 2 then raise exception 'Invalid message package'; end if;
    v_first := p_messages->0;
    select value into v_sender from jsonb_array_elements(v_game.state->'teams') where value->>'teamId' = v_member.seat_team_id and value->>'manager' = 'human';
    if v_sender is null or v_first->>'fromTeamId' is distinct from v_member.seat_team_id then raise exception 'You can only speak for your own team'; end if;
    select value into v_target from jsonb_array_elements(v_game.state->'teams') where value->>'teamId' = v_first->>'toTeamId';
    if v_target is null or v_target->>'teamId' = v_member.seat_team_id then raise exception 'Choose another manager in your league'; end if;
    if v_target->>'manager' = 'human' and not exists(select 1 from time_league_members where league_id = p_league_id and seat_team_id = v_target->>'teamId' and user_id is not null and joined_at is not null) then raise exception 'That manager has not joined the league yet'; end if;
    if v_first->>'id' is null or v_first->>'id' !~ '^chat:[A-Za-z0-9_-]{8,80}$' then raise exception 'Invalid send identifier'; end if;

    -- Exact retries are acknowledged before CAS, rate checks, or AI updates.
    select payload into v_existing from time_league_messages where league_id = p_league_id and message_id = v_first->>'id';
    if found then
        if (v_existing->>'fromTeamId',v_existing->>'toTeamId',v_existing->>'text',v_existing->>'tone',coalesce(v_existing->>'replyToId',''))
            is distinct from (v_first->>'fromTeamId',v_first->>'toTeamId',v_first->>'text',v_first->>'tone',coalesce(v_first->>'replyToId','')) then
            raise exception 'That message identifier was already used';
        end if;
        return jsonb_build_object('ok',true,'version',v_game.version,'deduplicated',true);
    end if;
    if p_expected_version is null or p_expected_version <> v_game.version then return jsonb_build_object('ok',false,'conflict',true); end if;
    select count(*) into v_count from time_league_messages where league_id = p_league_id and from_team_id = v_member.seat_team_id and message_id like 'chat:%' and created_at > v_now - interval '1 minute';
    if v_count >= 10 then raise exception 'Give that manager a moment before sending another message'; end if;
    v_week := least(20,greatest(1,coalesce(v_game.current_week,1)));
    v_message_week := greatest(1,v_week - case when v_game.state->>'weekStage' = 'postgame' then 1 else 0 end);
    if jsonb_array_length(p_messages) <> (case when v_target->>'manager' = 'ai' then 2 else 1 end) then raise exception 'Invalid reply package'; end if;

    for v_index in 0..jsonb_array_length(p_messages)-1 loop
        v_message := p_messages->v_index;
        if jsonb_typeof(v_message) is distinct from 'object'
            or (v_message - array['id','fromTeamId','toTeamId','text','tone','week','createdAt','sequence','replyToId']) <> '{}'::jsonb
            or jsonb_typeof(v_message->'text') is distinct from 'string'
            or char_length(v_message->>'text') not between 1 and 500 or btrim(v_message->>'text') = ''
            or jsonb_typeof(v_message->'tone') is distinct from 'string' or v_message->>'tone' not in ('neutral','friendly','competitive','dismissive')
            or jsonb_typeof(v_message->'week') is distinct from 'number' or v_message->>'week' not in (v_message_week::text,v_week::text)
            or jsonb_typeof(v_message->'sequence') is distinct from 'number' or v_message->>'sequence' !~ '^[1-9][0-9]{0,8}$'
            or jsonb_typeof(v_message->'createdAt') is distinct from 'string' then raise exception 'Invalid message fields'; end if;
        -- Timestamps in the persisted payload are always assigned by the DB.
        if v_index = 1 and (v_message->>'id' is distinct from 'reply:' || substring(v_first->>'id' from 6)
            or v_message->>'fromTeamId' is distinct from v_target->>'teamId'
            or v_message->>'toTeamId' is distinct from v_member.seat_team_id
            or v_message->>'tone' is distinct from 'neutral'
            or v_message->>'replyToId' is distinct from v_first->>'id') then raise exception 'Invalid AI reply'; end if;
        if v_message ? 'replyToId' then
            v_reply := v_message->>'replyToId';
            if jsonb_typeof(v_message->'replyToId') is distinct from 'string' or char_length(v_reply) not between 1 and 160 then raise exception 'Invalid reply reference'; end if;
            if v_index = 0 and v_reply ~ '^(chat|reply):' and not exists(select 1 from time_league_messages where league_id=p_league_id and message_id=v_reply and (from_team_id,to_team_id) in ((v_member.seat_team_id,v_target->>'teamId'),(v_target->>'teamId',v_member.seat_team_id))) then raise exception 'That message is not part of this conversation'; end if;
            if v_index = 0 and v_reply !~ '^(chat|reply|game|trade|waiver):' then raise exception 'Invalid reply reference'; end if;
        end if;
    end loop;

    if v_target->>'manager' = 'ai' then
        if jsonb_typeof(p_relationship) is distinct from 'object'
            or (p_relationship - array['ownerTeamId','otherTeamId','heat','updatedWeek']) <> '{}'::jsonb
            or p_relationship->>'ownerTeamId' is distinct from v_target->>'teamId'
            or p_relationship->>'otherTeamId' is distinct from v_member.seat_team_id
            or jsonb_typeof(p_relationship->'heat') is distinct from 'number'
            or p_relationship->>'heat' !~ '^-?[0-6]$'
            or jsonb_typeof(p_relationship->'updatedWeek') is distinct from 'number'
            or p_relationship->>'updatedWeek' is distinct from v_week::text then raise exception 'Invalid rivalry update'; end if;
        select value into v_previous from jsonb_array_elements(coalesce(v_game.state->'rivalRelationships','[]'::jsonb))
            where value->>'ownerTeamId'=v_target->>'teamId' and value->>'otherTeamId'=v_member.seat_team_id limit 1;
        v_heat := coalesce((v_previous->>'heat')::integer,0);
        v_heat := sign(v_heat) * greatest(0,abs(v_heat) - greatest(0,v_week - coalesce((v_previous->>'updatedWeek')::integer,v_week)));
        v_heat := least(6,greatest(-6,v_heat + case v_first->>'tone' when 'friendly' then -2 when 'competitive' then 2 when 'dismissive' then 1 else 0 end));
        if (p_relationship->>'heat')::integer <> v_heat then raise exception 'Invalid rivalry update'; end if;
        select coalesce(jsonb_agg(value),'[]'::jsonb) into v_relationships from jsonb_array_elements(coalesce(v_game.state->'rivalRelationships','[]'::jsonb))
            where not (value->>'ownerTeamId'=v_target->>'teamId' and value->>'otherTeamId'=v_member.seat_team_id);
        v_relationships := v_relationships || jsonb_build_array(p_relationship);
    elsif p_relationship is not null and p_relationship <> 'null'::jsonb then raise exception 'Human conversations do not change AI relationships'; end if;

    for v_message in select value from jsonb_array_elements(p_messages) loop
        v_message := jsonb_set(v_message,'{createdAt}',to_jsonb(v_now));
        v_message := jsonb_set(v_message,'{week}',to_jsonb(v_message_week));
        insert into time_league_messages(league_id,message_id,from_team_id,to_team_id,payload,created_at)
            values(p_league_id,v_message->>'id',v_message->>'fromTeamId',v_message->>'toTeamId',v_message,v_now);
    end loop;
    update time_leagues set state = case when v_relationships is null then state - 'rivalMessages'
            else jsonb_set(state - 'rivalMessages','{rivalRelationships}',v_relationships) end,
        version = version + 1 where id=p_league_id;
    return jsonb_build_object('ok',true,'version',v_game.version+1);
end $function$

CREATE OR REPLACE FUNCTION public.set_time_league_ready(p_user_id uuid, p_league_id uuid, p_ready boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_week integer;
    v_phase text;
    v_started boolean;
    v_previous integer;
    v_target integer;
begin
    select current_week, phase, draft_started into v_week, v_phase, v_started
        from time_leagues where id = p_league_id for update;
    if not found or v_phase is null or v_phase not in ('draft', 'season') then
        raise exception 'Readiness is available during the draft or season';
    end if;
    if v_phase = 'draft' and not v_started then
        raise exception 'Wait for the commissioner to open the draft room';
    end if;

    select ready_week into v_previous from time_league_members
        where league_id = p_league_id and user_id = p_user_id and joined_at is not null
        for update;
    if not found then raise exception 'You do not have a joined seat'; end if;

    v_target := case when p_ready then v_week else 0 end;
    -- Reconnects and repeated polling may send the same readiness twice. They
    -- must not invalidate an otherwise-current draft pick or bid.
    if v_previous = v_target then return; end if;
    update time_league_members set ready_week = v_target
        where league_id = p_league_id and user_id = p_user_id;
    update time_leagues set version = version + 1 where id = p_league_id;
end $function$

